class LanTests(unittest.TestCase):
    """Exercise the real LAN setup without requiring ESP32 hardware."""

    def setUp(self):
        """Load main.py with mocked MicroPython modules and no startup loop."""
        self.lan = Mock()
        self.network = types.SimpleNamespace(LAN=Mock(return_value=self.lan), PHY_IP101=1)
        machine = types.SimpleNamespace(Pin=Mock())
        machine.Pin.IN = 0
        with patch.dict(sys.modules, {"machine": machine, "network": self.network}):
            self.setup_lan = runpy.run_path(os.path.join(os.path.dirname(__file__), "main.py"))["setup_lan"]

    def test_dhcp_does_not_use_non_idempotent_ifconfig(self):
        """Avoid restarting DHCP through the legacy API when it is already running."""
        self.lan.ifconfig.side_effect = RuntimeError("Wifi Unknown Error 0x5004")
        self.assertIs(self.setup_lan(web.DEFAULT_CONFIG), self.lan)
        self.assertEqual(self.lan.method_calls, [call.active(False), call.ipconfig(dhcp4=True), call.active(True)])
        self.lan.ipconfig.assert_called_once_with(dhcp4=True)
        self.lan.ifconfig.assert_not_called()

    def test_configure_dhcp_before_link_events_can_start_it(self):
        """Reproduce a DHCP race if configuration happens while Ethernet is active."""
        def configure_dhcp(*, dhcp4):
            """Model a DHCP start racing with automatic LAN link events."""
            self.assertTrue(dhcp4)
            if self.lan.active.call_args != call(False):
                raise RuntimeError("Wifi Unknown Error 0x5004")

        self.lan.ipconfig.side_effect = configure_dhcp
        self.assertIs(self.setup_lan(web.DEFAULT_CONFIG), self.lan)
        self.assertEqual(self.lan.active.call_args, call(True))

    def test_static_ip_is_unchanged(self):
        """Keep the existing static IP, netmask, gateway and DNS configuration."""
        self.setup_lan(dict(web.DEFAULT_CONFIG, dhcp=False))
        self.lan.ifconfig.assert_called_once_with(
            ("192.168.1.200", "255.255.255.0", "192.168.1.1", "192.168.1.1"))
        self.assertEqual(self.lan.method_calls, [call.active(False), call.ifconfig(
            ("192.168.1.200", "255.255.255.0", "192.168.1.1", "192.168.1.1")), call.active(True)])
        self.lan.ipconfig.assert_not_called()

    def test_real_dhcp_errors_are_not_suppressed(self):
        """Report genuine DHCP startup failures instead of hiding network faults."""
        self.lan.ipconfig.side_effect = RuntimeError("Wifi Unknown Error 0x5003")
        with self.assertRaisesRegex(RuntimeError, "0x5003"):
            self.setup_lan(web.DEFAULT_CONFIG)
        self.assertEqual(self.lan.active.call_args, call(False))


class ConfigTests(unittest.TestCase):
    """Check validation, decoding and durable settings without hardware."""

    def test_roundtrip_and_failed_write(self):
        """Keep the previous settings when validation or file replacement fails."""
        with tempfile.TemporaryDirectory() as directory:
            with patch.object(web, "CONFIG_FILE", os.path.join(directory, "config.json")):
                web.save_config(web.DEFAULT_CONFIG)
                self.assertEqual(web.load_config(), web.DEFAULT_CONFIG)
                with self.assertRaises(ValueError):
                    web.save_config(dict(web.DEFAULT_CONFIG, mqtt_port=0))
                with patch.object(web.os, "rename", side_effect=OSError):
                    with self.assertRaises(OSError):
                        web.save_config(dict(web.DEFAULT_CONFIG, mqtt_topic="new/topic"))
                self.assertEqual(web.load_config(), web.DEFAULT_CONFIG)
                self.assertFalse(os.path.exists(web.CONFIG_FILE + ".tmp"))

    def test_bad_file_recovers_to_dhcp(self):
        """Corrupt configuration must not make the board permanently unreachable."""
        with tempfile.TemporaryDirectory() as directory:
            with patch.object(web, "CONFIG_FILE", os.path.join(directory, "config.json")):
                with open(web.CONFIG_FILE, "w") as stream:
                    stream.write('{"dhcp": false}')
                with patch("builtins.print"):
                    self.assertTrue(web.load_config()["dhcp"])

    def test_static_ip_and_validation(self):
        """Reject invalid subnets, host addresses, topics and numeric fields."""
        static = dict(web.DEFAULT_CONFIG, dhcp=False)
        self.assertEqual(web.validate_config(static), static)
        for changes in ({"ip": "192.168.1.0"}, {"ip": "192.168.1.255"},
                        {"ip": "192.168.01.2"}, {"ip": "256.1.1.1"},
                        {"gateway": "10.0.0.1"}, {"gateway": static["ip"]},
                        {"netmask": "255.0.255.0"}, {"netmask": "255.255.255.255"},
                        {"mqtt_port": True}, {"mqtt_port": 65536}, {"interval": 0},
                        {"mqtt_topic": "a/#"}, {"mqtt_server": "http://broker"},
                        {"mqtt_user": "admin\r\n"}):
            with self.subTest(changes=changes), self.assertRaises(ValueError):
                web.validate_config(dict(static, **changes))

    def test_form_decoding(self):
        """Decode UTF-8, plus, ampersand and equals without losing password bytes."""
        self.assertEqual(web.decode_form(b"key=a%2Bb%26c%3D&label=K%C3%BCche+1"),
                         {"key": "a+b&c=", "label": "K\u00fcche 1"})
        for body in (b"key=%", b"key=%GG", b"key=1&key=2", b"missing_equals"):
            with self.subTest(body=body), self.assertRaises(ValueError):
                web.decode_form(body)

    def test_password_preserve_replace_clear(self):
        """Blank password keeps the stored value; deletion is explicit."""
        previous = dict(web.DEFAULT_CONFIG, mqtt_password="secret")
        fields = dict(previous, dhcp="yes", mqtt_port="1883", interval="5",
                      csrf="token", clear_password="no", mqtt_password="")
        self.assertEqual(web.form_config(fields, previous)["mqtt_password"], "secret")
        fields["mqtt_password"] = " a+b&= "
        self.assertEqual(web.form_config(fields, previous)["mqtt_password"], " a+b&= ")
        fields["clear_password"] = "yes"
        self.assertEqual(web.form_config(fields, previous)["mqtt_password"], "")


class MemoryWriter:
    """Collect complete HTTP replies without a real socket."""

    def __init__(self):
        """Initialize reply buffer and close flag."""
        self.data = bytearray()
        self.closed = False

    def write(self, data):
        """Append bytes written by the server."""
        self.data.extend(data)

    async def drain(self):
        """Yield like a network stream."""
        await asyncio.sleep(0)

    def close(self):
        """Record that the handler released the client."""
        self.closed = True

    async def wait_closed(self):
        """Match the asyncio stream close API."""
        return None


class HttpTests(unittest.IsolatedAsyncioTestCase):
    """Check login-free HTTP behavior, form protection and restart scheduling."""

    def setUp(self):
        """Build a LAN server with a stored MQTT password that must stay private."""
        self.restart = Mock()
        self.server = web.ConfigServer(
            dict(web.DEFAULT_CONFIG, mqtt_password="DO_NOT_DISCLOSE"),
            lambda: {"ip": "192.168.1.20", "temperature": 24.5, "mqtt": "getrennt"},
            self.restart,
        )

    async def request(self, method="GET", path="/", body=b"", extra=""):
        """Feed a complete request through the actual handler and parse the reply."""
        raw = (method + " " + path + " HTTP/1.1\r\nHost: device\r\n"
               + "Content-Length: " + str(len(body)) + "\r\n" + extra + "\r\n").encode() + body
        reader = asyncio.StreamReader()
        reader.feed_data(raw)
        reader.feed_eof()
        writer = MemoryWriter()
        await self.server.handle(reader, writer)
        self.assertTrue(writer.closed)
        headers, payload = bytes(writer.data).split(b"\r\n\r\n", 1)
        self.assertIn(b"Content-Length: " + str(len(payload)).encode(), headers)
        self.assertIn(b"Cache-Control: no-store", headers)
        self.assertNotIn(b"WWW-Authenticate", headers)
        self.assertNotIn(b"DO_NOT_DISCLOSE", payload)
        return headers, payload

    def form(self, **changes):
        """Generate the full browser form using the server's current CSRF token."""
        fields = dict(web.DEFAULT_CONFIG, dhcp="yes", mqtt_password="",
                      clear_password="no", csrf=self.server.csrf)
        fields.update(changes)
        return urlencode(fields).encode()

    async def test_no_login_and_read_only_get(self):
        """Allow the form without credentials but reject the old mutating GET endpoint."""
        headers, payload = await self.request()
        self.assertIn(b"200 OK", headers)
        self.assertIn(self.server.csrf.encode(), payload)
        self.assertFalse(hasattr(self.server, "authorization"))
        headers, _ = await self.request(path="/save?mqtt_port=1234")
        self.assertIn(b"404 Not Found", headers)
        self.restart.assert_not_called()

    async def test_page_and_temperature(self):
        """Serve an escaped form and keep the existing temperature API."""
        self.server.config["mqtt_user"] = '<script>alert("x")</script>'
        headers, payload = await self.request()
        self.assertIn(b"200 OK", headers)
        self.assertIn(b"&lt;script&gt;", payload)
        self.assertNotIn(b"<script>", payload)
        headers, payload = await self.request(path="/api/temperature")
        self.assertIn(b"200 OK", headers)
        self.assertEqual(json.loads(payload), {"temperature": 24.5, "unit": "\u00b0C", "sensor": "OK"})

    async def test_mqtt_and_api_have_identical_temperature_json(self):
        """Compare a real publisher call with the API response for the same reading."""
        with patch.dict(sys.modules, {"machine": types.SimpleNamespace(), "network": types.SimpleNamespace()}):
            namespace = runpy.run_path(os.path.join(os.path.dirname(__file__), "main.py"))
        device_class = namespace["Device"]
        clock = types.SimpleNamespace(ticks_ms=lambda: 100000,
                                      ticks_add=lambda value, delta: value + delta,
                                      ticks_diff=lambda first, second: first - second)
        lan = Mock()
        lan.isconnected.return_value = True
        with patch.dict(device_class.__init__.__globals__, {"time": clock, "MQTTClient": Mock()}):
            device = device_class(dict(web.DEFAULT_CONFIG, mqtt_server="broker.local"), lan, None)
            client = Mock()
            device.client = client
            device.last_sample = clock.ticks_ms()
            for temperature in (24.5, -12.75, 0):
                with self.subTest(temperature=temperature):
                    device.temperature = temperature
                    device.last_publish = 0
                    device.sensor_status = "OK"
                    self.server.status = Mock(return_value={"temperature": temperature, "sensor": "OK"})
                    device.step()
                    _, payload = await self.request(path="/api/temperature")
                    self.assertEqual(client.publish.call_args.args[1], payload)
                    self.assertEqual(json.loads(payload), {"temperature": temperature, "unit": "\u00b0C", "sensor": "OK"})

    async def test_temperature_api_preserves_null_on_sensor_fault(self):
        """Keep the unit present when no valid measurement is available."""
        self.server.status = Mock(return_value={"temperature": None,
                                                "sensor": "Thermoelement offen/nicht angeschlossen"})
        _, payload = await self.request(path="/api/temperature")
        self.assertEqual(json.loads(payload), {"temperature": None, "unit": "\u00b0C",
                                                  "sensor": "Thermoelement offen/nicht angeschlossen"})

    async def test_csrf_and_invalid_form_do_not_write(self):
        """Reject foreign requests and invalid ports before touching flash."""
        with patch.object(web, "save_config") as save:
            headers, _ = await self.request("POST", "/save", self.form(csrf="wrong"),
                                            extra="Content-Type: application/x-www-form-urlencoded\r\n")
            self.assertIn(b"403 Forbidden", headers)
            headers, _ = await self.request("POST", "/save", self.form(mqtt_port=0),
                                            extra="Content-Type: application/x-www-form-urlencoded\r\n")
            self.assertIn(b"400 Bad Request", headers)
            save.assert_not_called()
            self.restart.assert_not_called()

    async def test_save_once_and_restart(self):
        """Persist validated settings before scheduling exactly one reboot."""
        with patch.object(web, "save_config") as save:
            headers, _ = await self.request("POST", "/save", self.form(mqtt_server="broker.local"),
                                            extra="Content-Type: application/x-www-form-urlencoded\r\n")
            self.assertIn(b"200 OK", headers)
            self.assertEqual(save.call_args.args[0]["mqtt_password"], "DO_NOT_DISCLOSE")
            self.restart.assert_called_once()
            headers, _ = await self.request("POST", "/save", self.form(),
                                            extra="Content-Type: application/x-www-form-urlencoded\r\n")
            self.assertIn(b"409 Conflict", headers)
            save.assert_called_once()

    async def test_malformed_request_does_not_leak_config(self):
        """Malformed headers must receive a bounded error without settings data."""
        headers, payload = await self.request(extra="Broken-Header\r\n")
        self.assertIn(b"400 Bad Request", headers)
        self.assertNotIn(self.server.csrf.encode(), payload)
        self.assertNotIn(b"mqtt_user", payload)

    async def test_fragmented_request_and_limits(self):
        """Handle split TCP headers/bodies and reject oversized declared bodies."""
        reader = asyncio.StreamReader()
        raw = b"POST /save HTTP/1.1\r\nContent-Length: 3\r\n\r\na=1"
        task = asyncio.create_task(self.server.read_request(reader))
        for offset in range(0, len(raw), 7):
            reader.feed_data(raw[offset:offset + 7])
            await asyncio.sleep(0)
        self.assertEqual((await task)[3], b"a=1")
        reader = asyncio.StreamReader()
        reader.feed_data(b"POST /save HTTP/1.1\r\nContent-Length: 4097\r\n\r\n")
        with self.assertRaises(ValueError):
            await self.server.read_request(reader)


